/**
 * Invoke or update a ref, depending on whether it is a function or object ref.
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode The VNode the ref belongs to. Holds any cleanup
 * function returned by a callback ref.
 * @param {VNode} [errorVNode] The VNode to attribute errors to. Defaults to
 * `vnode`.
 */
RefHost.prototype.applyRef = function (ref, value, vnode, errorVNode) {
	try {
		if (
			value != this._empty &&
			vnode != null &&
			vnode.constructor === undefined
		) {
			if (
				typeof vnode.type == this._fnType &&
				vnode._component != this._empty
