			if (
				value == this._empty &&
				vnode != null &&
				vnode._refCleanup != null
			) {
				// The ref returned a cleanup function when it was attached,
				// so invoke it instead of calling the ref with `null`
				const cleanup = vnode._refCleanup;
				vnode._refCleanup = undefined;
				cleanup();
