				if (vnode != null) {
					vnode._refCleanup =
						typeof cleanup == 'function' ? cleanup : undefined;
				}
			}
		} else {
			ref.current = value;
		}
	} catch (e) {
		options._catchError(e, errorVNode || vnode);
	}
};

